    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timezone = timezone.utc
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self.defaults = defaults
        self.sections = sections  # stream name -> {key: value}

    def streams(self) -> set[str]:
        return set(self.sections)

    def settings(self, name: str) -> Settings:
        merged = dict(self.defaults)
        merged.update(self.sections.get(name, {}))
        return Settings(**merged)


def _bad(path: Path, lineno: int, why: str) -> DataError:
    return DataError("policy", f"{path.name}:{lineno}: {why}")


def _size(v):
    m = re.fullmatch(r"([0-9]+)([KkMmGg]?)", v)
    if not m:
        raise ValueError(v)
    unit = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]
    return int(m.group(1)) * unit


def _off_or(parse):
    return lambda v: None if v == "off" else parse(v)


def _duration(v):
    m = re.fullmatch(r"([0-9]+)([mhd])", v)
    if not m:
        raise ValueError(v)
    unit = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}[m.group(2)]
    return int(m.group(1)) * unit


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError(v)
    return v


def _offset(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise ValueError(v)
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(delta if m.group(1) == "+" else -delta)


def _count(minimum):
    def parse(v):
        if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
            raise ValueError(v)
        return int(v)

    return parse


