import gzip
import re
from dataclasses import dataclass
from datetime import date, datetime
from pathlib import Path

from logkeep import dates, policy, streams
from logkeep.errors import DataError, Refused

_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?")
_DATED = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?")


@dataclass
class Item:
    """One archive of a stream, before or after the run."""

    order: tuple  # sorts the newest first
    gz: bool
    old: str | None  # file name before the run; None for the new archive
    base: str = ""  # dated: the name without `.gz`
    day: date | None = None
    k: int = 1
    time_text: str | None = None
    final: str = ""
    compress: bool = False


# ---------------------------------------------------------------- state checks

def check_state(doc: dict, existing: set[str]) -> None:
    for name in existing:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        if "opened" in entry and dates.parse_state_time(entry["opened"]) is None:
            raise DataError("state", f"{name}: opened is not a time")
        if "archives" in entry:
            archives = entry["archives"]
            if not isinstance(archives, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for key, value in archives.items():
                if dates.parse_state_time(value) is None:
                    raise DataError("state", f"{name}: time of {key} is not a time")
        if "rotations" in entry:
            r = entry["rotations"]
            if type(r) is not int:
                raise DataError("state", f"{name}: rotations is not a whole number")


# -------------------------------------------------------------------- archives

def scan(data: Path, name: str, naming: str) -> list[Item]:
    """The archives of a stream, newest first."""
    d = streams.logs_dir(data)
    prefix = f"{name}.log."
    found: dict[tuple, Item] = {}
    if d.is_dir():
        for p in d.iterdir():
            fname = p.name
            if not fname.startswith(prefix) or not p.is_file():
                continue
            rest = fname[len(prefix):]
            if naming == "numbered":
                m = _NUMBERED.fullmatch(rest)
                if not m:
                    continue
                n = int(m.group(1))
                item = Item(order=(n,), gz=bool(m.group(2)), old=fname)
                place = (n,)
            else:
                m = _DATED.fullmatch(rest)
                if not m:
                    continue
                try:
                    day = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
                except ValueError:
                    continue
                k = int(m.group(4)) if m.group(4) else 1
                item = Item(order=(-day.toordinal(), -k), gz=bool(m.group(5)), old=fname,
                            base=fname[: len(fname) - 3] if m.group(5) else fname, day=day, k=k)
                place = (day, k)
            if place in found:
                raise DataError("archives", f"{name}: two archives in the same place: {fname}, {found[place].old}")
            found[place] = item
    return sorted(found.values(), key=lambda i: i.order)


# ------------------------------------------------------------------ the rules

def first_line_time(path: Path) -> datetime | None:
    with path.open("rb") as f:
        line = f.readline()
    line = line.rstrip(b"\r\n") if b" " not in line else line
    token = line.split(b" ", 1)[0]
    try:
        return dates.parse_iso(token.decode("ascii"))
    except UnicodeDecodeError:
        return None


def decide(ctx, name, st: policy.Settings, entry: dict, force: bool) -> str:
    """The reason the stream is rotated, or the reason it is not."""
    path = streams.log_path(ctx.data, name)
    if not path.is_file():
        return "no log"
    size = path.stat().st_size
    if size == 0:
        return "empty"
    if force:
        return "forced"
    if st.max_size is not None and size >= st.max_size:
        return "size"
    if st.max_age is not None:
        if entry.get("opened") is not None:
            opened = dates.parse_state_time(entry["opened"])
        else:
            opened = first_line_time(path)
        if opened is not None and ctx.now - opened >= st.max_age:
            return "age"
    return "not due"


@dataclass
class StreamPlan:
    name: str
    what: str
    lines: list
    removed: list  # file names before the run, newest first
    removes: list  # paths
    moves: list  # (src path, dst path, compress)
    new: tuple | None  # (active path, dst path or None when removed at once, compress)
    entry: dict
    rotated: bool
    n_removed: int
    n_compressed: int


def plan_stream(ctx, name, st: policy.Settings, entry: dict, force: bool) -> StreamPlan:
