    keep, remaining, removed = st.keep, [], []
    for pos, it in enumerate(items, 1):
        drop = pos > keep
        if not drop and st.keep_days is not None and it.time_text is not None:
            t = dates.parse_state_time(it.time_text)
            drop = ctx.now - t >= st.keep_days * dates.DAY
        (removed if drop else remaining).append(it)

    n_compressed = 0
    for i, it in enumerate(remaining, 1):
        it.compress = not it.gz and i > st.compress_after
        gz = it.gz or it.compress
        n_compressed += it.compress
        if st.naming == "numbered":
            it.final = f"{name}.log.{i}"
        else:
            it.final = it.base
        if gz:
            it.final += ".gz"

    lines, removes, moves = [], [], []
    archives_state = {}
    new_op = None
    for it in remaining:
        if it is new:
            lines.append(f"  new {it.final}")
            new_op = (streams.log_path(ctx.data, name), logs / it.final, it.compress)
        elif it.final != it.old:
            lines.append(f"  {it.final} <- {it.old}")
            moves.append((logs / it.old, logs / it.final, it.compress))
        else:
            lines.append(f"  {it.final}")
        if it.time_text is not None:
            archives_state[it.final] = it.time_text
    removed_old = []
    for it in removed:
        if it is new:
            new_op = (streams.log_path(ctx.data, name), None, False)
            continue
        removed_old.append(it.old)
        lines.append(f"  remove {it.old}")
        removes.append(logs / it.old)

    new_entry = {}
    if entry.get("opened") is not None or "opened" in entry:
        new_entry["opened"] = entry["opened"]
    if rotated:
        new_entry["opened"] = ctx.stamp
    rotations = entry.get("rotations", 0)
    new_entry["rotations"] = rotations + (1 if rotated else 0)
    new_entry["archives"] = archives_state

    return StreamPlan(name, what, lines, removed_old, removes, moves, new_op, new_entry, rotated,
                      len(removed_old), n_compressed)


def _what(plan: StreamPlan) -> str:
    return f"rotate ({plan.what})" if plan.rotated else plan.what


def execute(plans: list[StreamPlan]) -> None:
    # read everything that has to move first, then remove, then write
    writes = []  # (dst, bytes)
    for p in plans:
        for src, dst, compress in p.moves:
            data = src.read_bytes()
            writes.append((dst, gzip.compress(data, mtime=0) if compress else data))
        if p.new is not None:
            active, dst, compress = p.new
            if dst is not None:
                data = active.read_bytes()
                writes.append((dst, gzip.compress(data, mtime=0) if compress else data))
    for p in plans:
        for path in p.removes:
            path.unlink()
        for src, _dst, _c in p.moves:
            src.unlink()
    for dst, data in writes:
        dst.write_bytes(data)
    for p in plans:
        if p.new is not None:
            p.new[0].write_bytes(b"")


def run(ctx, names: list[str], dry_run: bool, force: bool) -> list[str]:
    from logkeep import state

    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.streams()
    check_state(doc, existing)
    chosen = sorted(set(names)) if names else sorted(existing)
    for n in chosen:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")
    plans = []
    for n in chosen:
        entry = doc["streams"].get(n, {})
        plans.append(plan_stream(ctx, n, pol.settings(n), entry, force))

    out = []
    for p in plans:
        out.append(f"{p.name}: {_what(p)}")
        out.extend(p.lines)
    rotated = sum(p.rotated for p in plans)
    removed = sum(p.n_removed for p in plans)
    compressed = sum(p.n_compressed for p in plans)
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    execute(plans)
    new_doc = dict(doc)
    new_streams = dict(doc["streams"])
    for p in plans:
        new_streams[p.name] = p.entry
    new_doc["streams"] = new_streams
    ctx.state_path.parent.mkdir(parents=True, exist_ok=True)
    state.save(ctx.state_path, new_doc)
    return out
"}

